DROP FUNCTION IF EXISTS nexus.catalog_link_endpoint(jsonb);

changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.catalog_link_same_content(p_tumblers text[], p_prune boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
AS $fn$
DECLARE
    v_tenant    text := current_setting('nexus.tenant', true);
    v_cand      integer;
    v_csrc      text[];
    v_cdst      text[];
    v_live      integer;
    v_retracted text[] := '{}';
    v_n_retr    integer := 0;
    v_seed      text[];
    v_member    text;
    v_anchor    text;
    v_res       text;
    v_created   integer := 0;
BEGIN
    IF v_tenant IS NULL OR v_tenant = '' THEN
        RAISE EXCEPTION 'catalog_link_same_content no_tenant: nexus.tenant is not set';
    END IF;
    IF p_tumblers IS NULL OR cardinality(p_tumblers) = 0 THEN
        RETURN jsonb_build_object('created', 0, 'retracted', 0);
    END IF;

    -- ── prune: retract the stale dedup links that touch the given tumblers ──
    IF p_prune THEN
        -- candidates: same-as links by content_hash_dedup with an endpoint in scope; a link another creator also
        -- asserted (co_discovered_by set) is kept, because unlink deletes the whole row
        SELECT coalesce(array_agg(l.from_tumbler), '{}'), coalesce(array_agg(l.to_tumbler), '{}')
          INTO v_csrc, v_cdst
          FROM nexus.catalog_links l
         WHERE l.tenant_id = v_tenant AND l.link_type = 'same-as' AND l.created_by = 'content_hash_dedup'
           AND (l.from_tumbler = ANY (p_tumblers) OR l.to_tumbler = ANY (p_tumblers))
           AND coalesce(l.metadata -> 'co_discovered_by', 'null'::jsonb) IN ('null'::jsonb, '[]'::jsonb, '{}'::jsonb, '""'::jsonb, 'false'::jsonb, '0'::jsonb);
        v_cand := cardinality(v_csrc);

        IF v_cand > 0 THEN
            SELECT count(*) INTO v_live FROM nexus.catalog_documents d
             WHERE d.tenant_id = v_tenant AND d.deleted_at IS NULL AND d.content_type IN ('pdf', 'paper');
            IF v_live = 0 THEN
                -- reads as a failed fetch: acting on it would retract every link at once
                RETURN jsonb_build_object('created', 0, 'retracted', 0, 'refused', 'empty_fetch');
            END IF;

            -- a link is stale when an endpoint is no longer a live pdf/paper document, or when both endpoints have a
            -- settled key and the keys differ; an unsettled key (index_content_hash and the metadata hash both set
            -- and disagreeing) is unknown, not changed, and keeps the link. Each retraction is one row (from, to,
            -- same-as), never a bulk delete by creator.
            WITH k AS (
                SELECT d.tumbler,
                       CASE WHEN d.index_content_hash <> '' AND coalesce(d.metadata ->> 'content_hash', '') <> ''
                                 AND d.index_content_hash <> d.metadata ->> 'content_hash'
                            THEN ''
                            ELSE coalesce(nullif(d.index_content_hash, ''), d.metadata ->> 'content_hash', '') END AS skey
                  FROM nexus.catalog_documents d
                 WHERE d.tenant_id = v_tenant AND d.deleted_at IS NULL AND d.content_type IN ('pdf', 'paper')),
            pairs AS (
                SELECT c.src, c.dst, a.tumbler IS NOT NULL AND b.tumbler IS NOT NULL AS both_live,
                       a.skey AS askey, b.skey AS bskey
                  FROM unnest(v_csrc, v_cdst) AS c(src, dst)
                  LEFT JOIN k a ON a.tumbler = c.src
                  LEFT JOIN k b ON b.tumbler = c.dst),
            gone AS (
                DELETE FROM nexus.catalog_links l
                 USING pairs p
                 WHERE l.tenant_id = v_tenant AND l.from_tumbler = p.src AND l.to_tumbler = p.dst AND l.link_type = 'same-as'
                   AND NOT (p.both_live AND (p.askey = '' OR p.bskey = '' OR p.askey = p.bskey))
                RETURNING l.from_tumbler)
            SELECT coalesce(array_agg(from_tumbler), '{}') INTO v_retracted FROM gone;
            v_n_retr := cardinality(v_retracted);
        END IF;
    END IF;

    -- ── link: the given live pdf/paper members, and the from-side of every retracted link ──
    SELECT coalesce(array_agg(DISTINCT t), '{}') INTO v_seed
      FROM (SELECT d.tumbler AS t FROM nexus.catalog_documents d
             WHERE d.tenant_id = v_tenant AND d.deleted_at IS NULL AND d.content_type IN ('pdf', 'paper')
               AND d.tumbler = ANY (p_tumblers)
            UNION
            SELECT r FROM unnest(v_retracted) AS r) s;

    IF cardinality(v_seed) > 0 THEN
        -- groups are the live pdf/paper documents across the tenant, keyed by index_content_hash, else the metadata
        -- content_hash, never head_hash (nexus-utkop); the anchor is the least tumbler in "C" order (Python's
        -- min(str(tumbler)); a numeric order would re-anchor 1.2.9 and 1.2.10 and orphan their links). A group acts
        -- when it has a seed member; a seeded anchor gets every member, otherwise only the seeded members link.
        FOR v_member, v_anchor IN
            WITH docs AS (
                SELECT d.tumbler, coalesce(nullif(d.index_content_hash, ''), nullif(d.metadata ->> 'content_hash', '')) AS gkey
                  FROM nexus.catalog_documents d
                 WHERE d.tenant_id = v_tenant AND d.deleted_at IS NULL AND d.content_type IN ('pdf', 'paper')),
            grp AS (
                SELECT x.tumbler, x.gkey,
                       min(x.tumbler COLLATE "C") OVER (PARTITION BY x.gkey) AS anchor,
                       count(*) OVER (PARTITION BY x.gkey) AS n
                  FROM docs x
                 WHERE x.gkey IS NOT NULL
                   AND x.gkey IN (SELECT s.gkey FROM docs s WHERE s.tumbler = ANY (v_seed) AND s.gkey IS NOT NULL))
            SELECT g.tumbler, g.anchor FROM grp g
             WHERE g.n >= 2 AND g.tumbler <> g.anchor
               AND (g.anchor = ANY (v_seed) OR g.tumbler = ANY (v_seed))
             ORDER BY g.tumbler COLLATE "C"
        LOOP
            v_res := nexus.catalog_link_write(v_member, v_anchor, 'same-as', '', '', 'content_hash_dedup', true);
            IF v_res = 'created' THEN
                v_created := v_created + 1;
            END IF;
        END LOOP;
    END IF;

    RETURN jsonb_build_object('created', v_created, 'retracted', v_n_retr);
END;
$fn$;

GRANT EXECUTE ON FUNCTION nexus.catalog_link_same_content(text[], boolean) TO nexus_svc;
